{~~~google_font_weights~~~:~~~200,200italic,300,300italic,400,400italic,500,500italic,600,600italic,700,700italic,800,800italic,900,900italic~~~,~~~google_web_fonts~~~:[~~~Pacifico~~~,~~~Rajdhani~~~],~~~google_font_subset~~~:~~~latin,cyrillic-ext,cyrillic,greek-ext,greek,vietnamese,latin-ext~~~,~~~use_as_block~~~:~~~0~~~,~~~flexible_less~~~:[~~~_wrapper-product-10.less.css~~~,~~~_wrapper-product-11.less.css~~~,~~~_wrapper-product-12.less.css~~~,~~~_wrapper-product-05.less.css~~~,~~~_webkul-marketplace-01.less.css~~~],~~~product_view_less~~~:~~~_product-view-style-03.less.css~~~,~~~category_view_less~~~:~~~product-05.less.css~~~,~~~auto_import_less_files~~~:~~~1~~~,~~~version~~~:~~~68c43d5561e5f~~~,~~~custom_variables~~~:~~~~~~,~~~custom_less_code~~~:~~~.cdz-block-title {
    margin-bottom: 34px;

    .b-title.h2 {
        text-align: center;
        font-weight: 600;
        font-size: 32px;
    }
;
}

.hero-banner {
    .item-desc {
        position: absolute;
        left: 9%;
        top: 14%;

        h3 {
            font-size: 76px;
            line-height: 1.1;
            max-width: 666px;
            font-weight: bold;
            color: black;
        }

        h4 {
            font-size: 50px;
            font-weight: 400;
            text-align: center;
        }

        ul {
            margin-top: 35px;
            padding: 0;
            display: flex;
            gap: 25px;

            li {
                display: inline;

                a {
                    background: #645a4b;
                    color: white;
                    padding: 19px 25px;
                    border-radius: 10px;
                    display: inline-block;
                    font-size: 27px;
                }
            }
        }

        @media only screen and (max-width: 1679px) {
            h3 {
                font-size: 50px;
            }

            h4 {
                font-size: 30px;
                text-align: left;
            }

            ul {
                gap: 10px;

                li {
                    a {
                        padding: 14px 16px;
                        font-size: 16px;
                    }
                }
            }
        }

        @media only screen and (max-width: 767px) {
            left: 7%;
            top: 12%;

            h3 {
                font-size: 18px;
            }

            h4 {
                font-size: 15px;
            }

            ul {
                li {
                    a {
                        padding: 8px 10px;
                        font-size: 14px;
                    }
                }
            }
        }

        @media only screen and (min-width: 1680px) {
            left: 14%;
        }
    }
}

.trust-badges {
    margin-bottom: 70px;

    .badge-wrapper {
        padding: 48px 10px;
        border-top: 2px solid black;
        border-bottom: 2px solid black;
    }

    .cdz-shadow {
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 20px;

        img {
            height: 41px;
        }

        &.md-usa {
            justify-content: right;
        }

        &.next-day-ship {
            padding-left: 58px;
        }

        &.free-s {
            justify-content: left;
        }

        span {
            font-size: 32px;
            font-weight: bold;
        }

        @media only screen and (max-width: 1679px) {
            span {
                font-size: 19px;
            }
        }

        @media only screen and (max-width: 767px) {
            margin-bottom: 10px;
            justify-content: center !important;

            span {
                font-size: 18px;
            }

            &.next-day-ship {
                padding-left: unset;
            }
        }
    }
}

.best-seller-slider {
    .products-grid .product-item {
        padding: 10px;

        .product-item-actions {
            display: flex;
            justify-content: center;
        }
    }
}

.top-selling {
    padding-top: 41px;

    .cdz-block-title {
        margin-bottom: 47px;
    }
}

.cz-two-banner {
    text-align: center;
    padding-top: 72px;

    .column-banner {
        background: black;
        padding: 23px;
        padding-bottom: 44px;
        margin-bottom: 10px;
        border-radius: 40px;
        display: flex;
        flex-direction: column;
        align-items: center;

        &.builder-kit {
            margin-right: 40px;
        }

        &.upgrade-bundle {
            margin-left: 40px;
        }

        span {
            font-size: 50px;
            font-weight: bold;
            color: white;
            text-transform: uppercase;
        }

        a {
            padding: 22px 23px;
            color: white;
            background: #645a4b;
            border-radius: 15px;
            font-weight: 500;
            display: inline-block;
            font-size: 25px;
        }

        img {
            max-height: 370px;
            margin: 0 auto;
        }

        @media only screen and (max-width: 1679px) {
            margin-left: 0 !important;
            margin-right: 0 !important;

            span {
                font-size: 25px;
            }

            a {
                padding: 15px 20px;
                font-size: 20px;
            }
        }
    }
}

.best-seller-slider {
    padding-top: 40px;
}

.shop-now-banner {
    padding-top: 41px;

    .inner-content {
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        text-align: center;
        margin-top: 40px;
        width: 100%;

        h2 {
            font-size: 89px;
            color: white;
            margin-bottom: 26px;
        }

        a.button {
            background: #751309;
            color: white;
            font-size: 28px;
            font-weight: 600;
            border-radius: 8px;
            border: none;
            padding: 7px 100px;
        }
    }

    @media only screen and (max-width: 1679px) {
        .inner-content {
            h2 {
                font-size: 50px;
            }

            a.button {
                font-size: 20px;
                padding: 10px 21px;
            }
        }
    }

    @media only screen and (max-width: 767px) {
        padding-top: 0;

        .inner-content {
            margin-top: 0;

            h2 {
                font-size: 20px;
            }

            a.button {
                font-size: 16px;
            }
        }
    }
}

